function Get-OwnerHeaders($spec) { if ($spec.owner -eq 'yudao') { return $yudao } else { return $admin } }
function Approve-Node($headers, $instanceId, $reason) {
  $todo = (Api $headers GET '/bpm/task/todo-page?pageNo=1&pageSize=100').data.list | Where-Object { $_.processInstance.id -eq $instanceId }
  if (@($todo).Count -lt 1) { throw "no todo task for instance $instanceId" }
  $r = Api $headers PUT '/bpm/task/approve' @{ id = @($todo)[0].id; reason = $reason }
  if ($r.code -ne 0) { throw "approve failed: $($r.msg)" }
}
function Get-OffsetDays($state) {
  switch ($state) {
    'signed'        { return (Get-Random -Minimum 45 -Maximum 76) }
    'approved'      { return (Get-Random -Minimum 20 -Maximum 46) }
    'rejected'      { return (Get-Random -Minimum 10 -Maximum 41) }
    'running_node1' { return (Get-Random -Minimum 3  -Maximum 21) }
    'running_node2' { return (Get-Random -Minimum 3  -Maximum 21) }
    default         { return (Get-Random -Minimum 1  -Maximum 11) }
  }
}

$ContractIds = @{}
foreach ($cs in $ContractSpecs) {
  $owner = Get-OwnerHeaders $cs
  $body = @{
    title = $cs.title; typeId = $TypeIds[$cs.type]; amount = $cs.amount; currency = 'CNY'
    effectiveDate = $cs.eff; expiryDate = $cs.exp
    description = "$($cs.title)（演示数据）"
    customData = $cs.custom
    parties = @(
      @{ partyId = $PartyIds[$cs.our]; roleCode = 'OUR_SIDE'; sort = 1 },
      @{ partyId = $PartyIds[$cs.cp]; roleCode = 'COUNTERPARTY'; sort = 2 }
    )
  }
  $r = Api $owner POST '/clm/contract/create' $body
  if ($r.code -ne 0) { Step $false "create '$($cs.title)' (msg=$($r.msg))"; throw "contract create failed" }
  $cid = $r.data
  $ContractIds[$cs.key] = $cid
  $script:CreatedContractIds += @{ id = $cid; offsetDays = (Get-OffsetDays $cs.state) }

  if ($cs.doc) {
    $up = Upload $owner '/clm/contract/document/upload' @{ contractId = $cid; roleCode = 'MAIN'; remark = '正文 v1' } (Join-Path $DocDir $cs.doc)
    if ($up.code -ne 0) { Step $false "upload main doc for '$($cs.title)' (msg=$($up.msg))"; throw "doc upload failed" }
  }

  if ($cs.state -ne 'draft') {
    $r = Api $owner POST '/clm/contract/submit' @{ id = $cid; remark = '请审批' }
    if ($r.code -ne 0) { Step $false "submit '$($cs.title)' (msg=$($r.msg))"; throw "submit failed" }
    $bindingId = $r.data
    $binding = (Api $owner GET "/clm/workflow-binding/list?contractId=$cid").data | Where-Object { $_.id -eq $bindingId }
    $inst = $binding.processInstanceId
    Start-Sleep -Milliseconds 500

    if ($cs.state -eq 'rejected') {
      $todo = (Api $yudao GET '/bpm/task/todo-page?pageNo=1&pageSize=100').data.list | Where-Object { $_.processInstance.id -eq $inst }
      if (@($todo).Count -lt 1) { Step $false "no todo to reject for '$($cs.title)'"; throw "reject failed" }
      $r = Api $yudao PUT '/bpm/task/reject' @{ id = @($todo)[0].id; reason = $cs.rejectReason }
      if ($r.code -ne 0) { Step $false "reject '$($cs.title)' (msg=$($r.msg))"; throw "reject failed" }
    }
    elseif ($cs.state -in 'running_node2', 'approved', 'signed') {
      Approve-Node $yudao $inst '法务审核通过'
      Start-Sleep -Milliseconds 500
      if ($cs.state -in 'approved', 'signed') {
        Approve-Node $admin $inst '同意'
        Start-Sleep -Seconds 1
      }
    }
    # running_node1: submitted, no approval action -> waits at 法务 (yudao)
  }

  if ($cs.state -eq 'signed') {
    # archive with a stamped-scan placeholder (re-use the contract main DOCX as scan file)
    $scan = Join-Path $DocDir $cs.doc
    $arch = Upload $owner '/clm/contract/archive' @{ contractId = $cid; signDate = $cs.sign; effectiveDate = $cs.eff; expiryDate = $cs.exp } $scan
    if ($arch.code -ne 0) { Step $false "archive '$($cs.title)' (msg=$($arch.msg))"; throw "archive failed" }
  }

  # verify final state
  $c = (Api $owner GET "/clm/contract/get?id=$cid").data
  $ok = switch ($cs.state) {
    'draft'         { $c.approvalStatus -eq 0 -and $c.lifecycleStatus -eq 1 }
    'running_node1' { $c.approvalStatus -eq 1 }
    'running_node2' { $c.approvalStatus -eq 1 }
    'rejected'      { $c.approvalStatus -eq 3 -and $c.lifecycleStatus -eq 1 }
    'approved'      { $c.approvalStatus -eq 2 -and $c.lifecycleStatus -eq 2 }
    'signed'        { $c.approvalStatus -eq 2 -and $c.lifecycleStatus -eq 3 }
  }
  Step $ok "[$($cs.state)] id=$cid $($cs.title) (approval=$($c.approvalStatus) lifecycle=$($c.lifecycleStatus))"
}

# --------------------------------------- 5. copy / renewal relations (§3.5)
Write-Host "== step 5: copy + renewal relations"
$r = Api $admin POST '/clm/contract/copy' @{ sourceContractId = $ContractIds['sensor-sales']; relationType = 'COPY' }
Step ($r.code -eq 0) "copy of 华东区工业传感器年度销售框架合同 -> id=$($r.data) (msg=$($r.msg))"
if ($r.code -eq 0) { $script:CreatedContractIds += @{ id = $r.data; offsetDays = (Get-Random -Minimum 1 -Maximum 8) } }

$r = Api $admin POST '/clm/contract/copy' @{ sourceContractId = $ContractIds['office-lease']; relationType = 'RENEWAL'; title = '杭州研发中心办公场地租赁合同（2027年度续签）' }
Step ($r.code -eq 0) "renewal of 杭州研发中心办公场地租赁合同 -> id=$($r.data) (msg=$($r.msg))"
if ($r.code -eq 0) { $script:CreatedContractIds += @{ id = $r.data; offsetDays = (Get-Random -Minimum 1 -Maximum 8) } }

# --------------------------------------------- 6. backdate timestamps (§3.6)
Write-Host "== step 6: backdate timestamps via mysql (only rows created by this run)"
$envFile = Join-Path $ClmRoot 'infra\.env'
$dbPass = ((Get-Content $envFile | Where-Object { $_ -match '^CLM_DB_PASSWORD=' } | Select-Object -First 1) -replace '^CLM_DB_PASSWORD=', '').Trim()
$dbUser = ((Get-Content $envFile | Where-Object { $_ -match '^CLM_DB_USERNAME=' } | Select-Object -First 1) -replace '^CLM_DB_USERNAME=', '').Trim()
if (-not $dbUser) { $dbUser = 'root' }
$mysqlExe = Join-Path $ClmRoot 'runtime\tools\mysql-8.0.33-winx64\bin\mysql.exe'
if (-not (Test-Path $mysqlExe)) { Step $false "mysql.exe not found at $mysqlExe"; throw "mysql missing" }

$sqlLines = New-Object System.Collections.Generic.List[string]
# types + parties were created first: push them further back than any contract (fixed 80 days)
if ($script:CreatedTypeIds.Count -gt 0) {
  $in = ($script:CreatedTypeIds -join ',')
  $sqlLines.Add("UPDATE clm_contract_type SET create_time = DATE_SUB(create_time, INTERVAL 80 DAY), update_time = DATE_SUB(update_time, INTERVAL 80 DAY) WHERE id IN ($in);")
  $sqlLines.Add("UPDATE clm_contract_type_version SET create_time = DATE_SUB(create_time, INTERVAL 80 DAY), update_time = DATE_SUB(update_time, INTERVAL 80 DAY) WHERE type_id IN ($in);")
}
if ($script:CreatedPartyIds.Count -gt 0) {
  $in = ($script:CreatedPartyIds -join ',')
  $sqlLines.Add("UPDATE clm_party SET create_time = DATE_SUB(create_time, INTERVAL 80 DAY), update_time = DATE_SUB(update_time, INTERVAL 80 DAY) WHERE id IN ($in);")
}
# per-contract: shift every row of that contract by ONE offset so relative event order is preserved
foreach ($e in $script:CreatedContractIds) {
  $cid = $e.id; $d = $e.offsetDays
  $sqlLines.Add("UPDATE clm_contract SET create_time = DATE_SUB(create_time, INTERVAL $d DAY), update_time = DATE_SUB(update_time, INTERVAL $d DAY) WHERE id = $cid;")
  $sqlLines.Add("UPDATE clm_contract_party SET create_time = DATE_SUB(create_time, INTERVAL $d DAY), update_time = DATE_SUB(update_time, INTERVAL $d DAY) WHERE contract_id = $cid;")
  $sqlLines.Add("UPDATE clm_document SET create_time = DATE_SUB(create_time, INTERVAL $d DAY), update_time = DATE_SUB(update_time, INTERVAL $d DAY) WHERE contract_id = $cid;")
  $sqlLines.Add("UPDATE clm_document_version SET create_time = DATE_SUB(create_time, INTERVAL $d DAY), update_time = DATE_SUB(update_time, INTERVAL $d DAY) WHERE contract_id = $cid;")
  $sqlLines.Add("UPDATE clm_workflow_binding SET create_time = DATE_SUB(create_time, INTERVAL $d DAY), update_time = DATE_SUB(update_time, INTERVAL $d DAY) WHERE contract_id = $cid;")
  $sqlLines.Add("UPDATE clm_audit_event SET occurred_at = DATE_SUB(occurred_at, INTERVAL $d DAY), create_time = DATE_SUB(create_time, INTERVAL $d DAY), update_time = DATE_SUB(update_time, INTERVAL $d DAY) WHERE contract_id = $cid;")
}
$sqlFile = Join-Path $ClmRoot 'runtime\tmp\seed-backdate.sql'
New-Item -ItemType Directory -Force (Split-Path $sqlFile) | Out-Null
[IO.File]::WriteAllLines($sqlFile, $sqlLines)   # pure ASCII content
$env:MYSQL_PWD = $dbPass
$prevEap = $ErrorActionPreference; $ErrorActionPreference = 'Continue'   # native stderr must not throw under Stop
$out = Get-Content $sqlFile | & $mysqlExe "-u$dbUser" '--default-character-set=utf8mb4' 'ruoyi-vue-pro' 2>&1
$mysqlOk = ($LASTEXITCODE -eq 0)
$ErrorActionPreference = $prevEap
$env:MYSQL_PWD = $null
Step $mysqlOk "backdate SQL executed ($($sqlLines.Count) statements) $(if (-not $mysqlOk) { $out | Out-String })"

} catch {
  Write-Host "  FAIL  fatal: $($_.Exception.Message)" -ForegroundColor Red
  $script:Failures++
}

# ----------------------------------------------------------------- summary
Write-Host ""
Write-Host "created contract ids: $(($script:CreatedContractIds | ForEach-Object { $_.id }) -join ', ')"
if ($script:Failures -eq 0) { Write-Host "SEED COMPLETE - ALL STEPS PASSED" -ForegroundColor Green }
else { Write-Host "SEED FINISHED WITH $($script:Failures) FAILURE(S)" -ForegroundColor Red; exit 1 }
